def main():
    n = int(sys.stdin.readline().strip())
    count = 0
    for a in range(1, n + 1):
        for b in range(a, n + 1):
            c = a ^ b
            if c < b or c > n:
                continue
            if a + b > c:
                count += 1
    print(count)

if __name__ == "__main__":
    main()
